    ($sl$7.4 Figma-да вектор$sl$, 3, $sl${"summary":"Pen tool: түзу және қисық нүктелер, Edit vector, Boolean амалдары.","objectives":["Pen tool-мен тұйық пішін сызу","Нүктелерді өңдеу (Edit vector)","Boolean амалдарымен пішін құрау"],"grade":7,"duration":"40 минут"}$sl$::jsonb, $sl$[{"term":"Pen tool","definition":"нүкте қойып вектор сызатын құрал (P)"},{"term":"Boolean","definition":"фигураларды біріктіру, алып тастау, қиылыстыру амалдары"},{"term":"Edit vector","definition":"вектордың нүктелерін өңдеу режимі"}]$sl$::jsonb, $sl$[{"type":"title","pageType":"slide","templateId":"title","title":"Figma-да вектор","subtitle":"7.4 · Pen tool және Boolean"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Бүгін сен үйренесің","bullets":["1 · Pen tool-мен тұйық пішін сызу","2 · Нүктелерді өңдеу (Edit vector)","3 · Boolean амалдарымен жаңа пішін құрау"],"notes":"Жылыту: өткен сабақтан — растр мен вектордың бір айырмасы. Pen-мен жұмыс алғашында қиын: шыдамдылық керек, қатесіз бірден шықпайды."},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Pen tool (P)","bullets":["Бір рет бас — түзу нүкте қойылады","Басып сүйрей — қисық нүкте (тұтқа пайда болады)","Пішінді жабу үшін бірінші нүктеге қайта бас","Аяқтау: Esc немесе Enter","Өңдеу: пішінді екі рет бас, нүктені сүйре"],"notes":"Тұтқа (handle) қисықтың иілуін басқарады. Экранда жүрек немесе жапырақты 6-8 нүктемен сызып көрсетіңіз."},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Boolean амалдары","bullets":["Union — біріктіру","Subtract — үстіңгі фигураны алып тастау","Intersect — қиылысқан бөлікті қалдыру","Exclude — қиылыспаған бөліктерді қалдыру"],"code":"Шеңбер − шеңбер = жарты ай  (Subtract)\nШеңбер ∩ шеңбер = линза      (Intersect)\nШеңберлер қосындысы = бұлт     (Union)","lang":"text","notes":"Бірнеше фигураны таңдағанда жоғарғы тақтада Boolean түймелері пайда болады."},{"type":"solution","pageType":"slide","templateId":"worked-example","kind":"exampletask","title":"Жарты ай жасаймыз","sections":[{"h":"Шарты","text":"Boolean-мен жарты ай және жұлдыз белгісін жина."},{"h":"Қадамдар","bullets":["Үлкен шеңбер (Ellipse) сыз","Оның оң жағына кішірек шеңбер қой, ішінара жабатындай","Екеуін таңда, жоғарыдан Subtract таңда","Pen-мен жанына 5 бұрышты жұлдыз сыз: 10 нүкте, соңында жаб","Fill түстерін бер"]},{"h":"Нәтиже","text":"Жарты ай (Boolean) және жұлдыз (Pen) бір Frame-де","hide":true}],"notes":"Subtract кезінде үстіңгі фигура алынып тасталады, сондықтан кішірек шеңбер жоғарыда тұруы керек."},{"type":"content","pageType":"slide","templateId":"practice","kind":"practice","title":"Практика: белгі жасау","bullets":["1. Pen-мен тұйық белгі сыз (жүрек, жапырақ немесе өз ойыңдағы), кемінде 1 қисық сызықты болсын","2. Fill түс бер","3. Boolean-мен екінші белгі жаса (Union, Subtract немесе Intersect)","4. Екі белгіге ат бер"],"notes":"Тапсырма Figma-да орындалады. Мұғалімнің белгілеуі: орындалды — 1, орындалмады — 0."},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Бағалау критерийі","bullets":["1 · Pen-мен жасалған тұйық белгі бар","2 · Белгіде кемінде бір қисық сызық бар","3 · Boolean-мен жасалған екінші белгі бар","4 · Қабаттары аталған","Әр критерий: орындалды — 1, орындалмады — 0. Барлығы 4 ұпай."]},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Өзіңді тексер · 1","prompt":"Pen tool-мен қисық нүктені қалай қоямыз?","options":["Бір рет басып","Басып, сүйреп","Екі рет басып","Shift ұстап"],"answer":1,"explanation":"Басып сүйресең, қисықтың тұтқасы пайда болады.","points":1},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Өзіңді тексер · 2","prompt":"Subtract нәтижесі қандай?","options":["Екі фигура да жоғалады","Төменгіден үстіңгі фигура алынып тасталады","Фигуралар біріктіріледі","Тек қиылысқаны қалады"],"answer":1,"explanation":"Subtract — үстіңгі фигураны төменгіден алып тастау.","points":1},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Өзіңді тексер · 3","prompt":"Pen-мен сызуды қалай аяқтаймыз?","options":["Esc немесе Enter","Delete","Ctrl+Z","F"],"answer":0,"explanation":"Esc немесе Enter сызуды аяқтайды.","points":1}]$sl$::jsonb),
    ($sl$7.5 ЖИ-мен растрлық стикер$sl$, 4, $sl${"summary":"ЖИ-ға prompt жазу: кейіпкер, стиль, жай фон. 4 нұсқадан бірін таңдау. Ережелер: белгілі кейіпкер де, нақты адам да жоқ.","objectives":["Кейіпкер, стиль және фон бар prompt жазу","ЖИ нәтижесінен біреуін дәлелдеп таңдау","ЖИ-мен жұмыс ережелерін сақтау"],"grade":7,"duration":"40 минут"}$sl$::jsonb, $sl$[{"term":"prompt","definition":"ЖИ-ға жазылатын тапсырма мәтіні"},{"term":"стикер","definition":"ақ шеті бар, фоны жай шағын сурет"},{"term":"ЖИ","definition":"жасанды интеллект"}]$sl$::jsonb, $sl$[{"type":"title","pageType":"slide","templateId":"title","title":"ЖИ-мен растрлық стикер","subtitle":"7.5 · Prompt жазу, нұсқа таңдау"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Бүгін сен үйренесің","bullets":["1 · Кейіпкер, стиль және фон бар prompt жазу","2 · ЖИ шығарған нұсқалардан біреуін дәлелдеп таңдау","3 · ЖИ-мен жұмыс ережелерін сақтау"],"notes":"Алдын ала: мектептің AI құралына рұқсаты бар ма. Болмаса, жоспардағы нұсқа: мұғалім бір аккаунттан экранда жібереді, оқушылар prompt-тарды жұпта жазады. Сабақтың басында ережелерді (келесі екінші слайд) оқыңыз."},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Жақсы prompt","bullets":["Формула: кім/не + не істеп тұр + стиль + түс + фон","Нашар: «мысық»","Жақсы: «Көзілдірік киген қуанышты қызыл мысық, жалпақ (flat) стикер стилі, қалың контур, 3 түс, ақ фон»","Жай фон мен аз түс кейін векторға ауыстыруды жеңілдетеді"],"notes":"Неге «аз түс, жай фон»: келесі сабақта осы суретті қолмен векторлаймыз. Күрделі градиент пен ұсақ бөлшек жұмысты қиындатады."},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Ережелер","bullets":["Белгілі мультфильм кейіпкерлерін және нақты адамдарды жасатпаймыз","Өз кейіпкеріңді ойлап тап","Prompt-қа аты-жөніңді, мектебіңді, жеке дерегіңді жазбаймыз","ЖИ қателесуі мүмкін (артық саусақ, бұрмаланған мәтін) — нәтижені 