    ($sl$7.6 Растрды векторға айналдыру$sl$, 5, $sl${"summary":"Растрды Figma-ға салып, Pen tool-мен контур бойынша қайта сызу, үш түстік бөлікті бөлек толтыру.","objectives":["Растрды Figma-ға салып, оның үстінен сызу","Pen-мен контурды аз нүктемен қайта сызу","Бөліктерді бөлек толтыру"],"grade":7,"duration":"40 минут"}$sl$::jsonb, $sl$[{"term":"Opacity","definition":"мөлдірлік: 100% — толық көрінеді, 50% — жартылай"},{"term":"Lock","definition":"қабатты құлыптау, кездейсоқ жылжымасын"},{"term":"контур","definition":"пішіннің сыртқы жиегі"}]$sl$::jsonb, $sl$[{"type":"title","pageType":"slide","templateId":"title","title":"Растрды векторға айналдыру","subtitle":"7.6 · Pen-мен қайта сызу"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Бүгін сен үйренесің","bullets":["1 · Растр стикерді Figma-ға салып, үстінен сызу","2 · Pen-мен контурды аз нүктемен сызу","3 · Үш түстік бөлікті бөлек толтыру"],"notes":"Жылыту: өткен сабақтың prompt-ы. Бүгін негізгі жұмыс — 20 минут бір стикерді векторлау. Жұмыс ұзақ болады: бәрі үлгермесе, үйге тапсырма емес, келесі сабақта жалғасады."},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Калька әдісі","bullets":["Растрды Figma-ға сүйреп кіргіз","Opacity-ді 50%-ға түсір және құлыптап қой (Lock)","Үстінен Pen-мен контурды қайта сыз","Дайын болғанда растрды жасыр (қабаттың көз белгісі)"],"notes":"Опция: Figma-да Ctrl+Shift+L — қабатты құлыптау. Құлыптамаса, оқушылар кездейсоқ растрды жылжытып алады."},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Қалай дұрыс сызамыз","bullets":["Нүкте аз болсын (бір пішінге шамамен 8–15)","Қисық жерде нүктені басып сүйре","Әр бөлік бөлек пішін: дене, бет, бөлшек","Әр бөлікке бөлек түс (Fill), жалпы 3 түс","Нүкте тым көп болса, жиек иректелген болады"],"notes":"Жиі қате: оқушылар әр пиксельді қуып, 100 нүкте қояды. Аз нүкте = тегіс сызық."},{"type":"solution","pageType":"slide","te