mpt":"Контурды сызғанда нүкте қанша болғаны жақсы?","options":["Мүмкіндігінше көп","Аз, бірақ пішінді жеткізетін","Мүлде жоқ","Әр пиксельге бір нүкте"],"answer":1,"explanation":"Аз нүкте — тегіс және таза сызық.","points":1},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Өзіңді тексер · 3","prompt":"Үш түстік стикер қалай жасалады?","options":["Бір пішінге үш түс","Әр түсті бөлек пішінге беріп","Тек Stroke арқылы","Растрды бояп"],"answer":1,"explanation":"Әр бөлік бөлек пішін және бөлек Fill.","points":1}]$sl$::jsonb),
    ($sl$7.7 Жоба: стикерпак жинау$sl$, 6, $sl${"summary":"Қалған стикерлерді векторлау, ақ шет (Stroke), бір Frame-ге тор бойынша жинау, SVG және PNG экспорт.","objectives":["Қалған стикерлерді векторлау","Ақ шет (Stroke) қосу","Стикерлерді торға жинап, SVG және PNG экспорттау"],"grade":7,"duration":"40 минут"}$sl$::jsonb, $sl$[{"term":"Stroke","definition":"контур: түсі, қалыңдығы, орны"},{"term":"Export","definition":"Figma-дан файл ретінде сақтау"},{"term":"Align","definition":"элементтерді туралау"}]$sl$::jsonb, $sl$[{"type":"title","pageType":"slide","templateId":"title","title":"Жоба: стикерпак жинау","subtitle":"7.7 · Векторлау, ақ шет, жинау, Export"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Бүгін сен үйренесің","bullets":["1 · Қалған стикерлерді векторлау","2 · Ақ шет (Stroke) қосу","3 · Стикерлерді торға жинап, SVG және PNG экспорттау"],"notes":"Бұл жұмыс сабағы. Мұғалім қатарлап жүріп жеке кеңес береді. Бітіре алмағандарға қалған жұмысты үйге беріңіз, 8-сабақ қорғауға қалсын."},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Ақ шет (Stroke)","bullets":["Стикердің жиегіне ақ контур қосамыз","Stroke: түсі — ақ, орны — Outside, қалыңдығы — 6–8","Бұрыштар жұмсақ болу үшін Join параметрін Round қой"],"notes":"Ақ шет стикерді кез келген фонда ерекшелеп тұрады. Outside болмаса, контур стикердің ішіне түсіп кетеді."},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Жинау және Export","bullets":["Бір Frame, 2×2 тор: стикерлердің өлшемі бірдей, аралығы бірдей","Туралау: жоғарғы Align түймелері","Export: оң жақ төменде Export қос → SVG және PNG (2x)","Файл аттары: стикер_1 … стикер_4"],"notes":"Auto layout жоспарда 9-сыныпта; мұнда торды қолмен жинаймыз."},{"type":"solution","pageType":"slide","templateId":"worked-example","kind":"exampletask","title":"Экспорт жасаймыз","sections":[{"h":"Шарты","text":"Стикерпакты SVG және PNG түрінде сақта."},{"h":"Қадамдар","bullets":["Frame-ді таңда (стикерпак)","Оң жақ төменде Export жанындағы «+» бас","Форматты SVG таңда, тағы бір «+» басып PNG 2x таңда","Export бас, файлдарды қалтаңа сақта","SVG-ді браузерде ашып, үлкейтіп тексер"]},{"h":"Нәтиже","text":"Қалтада .svg және .png файлдары бар, SVG үлкейткенде анық қалады","hide":true}],"notes":"Файлды Google Drive/мектеп қалтасына тапсыруды ескертіңіз."},{"type":"content","pageType":"slide","templateId":"practice","kind":"practice","title":"Практика: стикерпак","bullets":["1. Қалған 3 стикерді векторла","2. Әрқайсысына ақ шет қос (Stroke, Outside)","3. Бір Frame-ге 2×2 торға жина, аралықтары бірдей","4. SVG және PNG экспорттап, қалтаға сал"],"notes":"Тапсырма Figma-да орындалады. Мұғалімнің белгілеуі: орындалды — 1, орындалмады — 0."},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Бағалау критерийі","bullets":["1 · 4 стикер векторлық (Pen-мен жасалған)","2 · Барлығында ақ шет бар","3 · Frame-де тор: өлшем мен аралық бірдей","4 · SVG және PNG экспортталған","Әр критерий: орындалды — 1, орындалмады — 0. Барлығы 4 ұпай."]},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Өзіңді тексер · 1","prompt":"Ақ шет үшін Stroke орнын қалай қоямыз?","options":["Inside","Center","Outside","Ешқандай"],"answer":2,"explanation":"Outside — контур стикердің сыртына шығады.","points":1},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Өзіңді тексер · 2","prompt":"Қай формат векторлық экспорт?","options":["PNG","JPG","SVG","GIF"],"answer":2,"explanation":"SVG — векторлық формат.","points":1},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Өзіңді тексер · 3","prompt":"Стикерпак торында не бірдей болуы керек?","options":["Түстері","Өлшемі мен аралығы","Тек аттары","Ештеңе"],"answer":1,"explanation":"Өлшем мен аралық бірдей болса, тор таза көрінеді.","points":1}]$sl$::jsonb),
    ($sl$7.8 Жобаны қорғау$sl$, 7, $sl${"summary":"Растр мен вектор нұсқасын қатар көрсетіп, вектордың артықшылығын түсіндіру. Сын-талқылау, портфолио және тоқсандық баға.","objectives":["Жобаны 2 минутта қорғау","Сынды қабылдап, бір өзгеріс енгізу","Жобаны портфолиоға салу"],"grade":7,"duration":"40 минут"}$sl$::jsonb, $sl$[{"term":"critique","definition":"сын-талқылау: жұмысты жақсарту үшін пікір алмасу"},{"term":"портфолио","definition":"жұмыстар жинағы"},{"term":"рефлексия","definition":"өз жұмысың туралы ойлану"}]$sl$::jsonb, $sl$[{"type":"title","pageType":"slide","templateId":"title","title":"Жобаны қорғау","subtitle":"7.8 · Стикерпак: растр → вектор"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Бүгін сен үйренесің","bullets":["1 · Жобаңды 2 минутта түсіндіру","2 · Сынды қабылдап, бір өзгеріс енгізу","3 · Жобаны портфолиоға салу"],"notes":"Тоқсандық жиынтық баға осы сабақта. Критерийлер 0–5 балл, барлығы 20 (соңғы слайдтағыдай). 5 баллдық бағаға ауыстыру шкаласын мектептің өз талабымен бекітіңіз."},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Қорғау құрылымы (2 минут)","bullets":["1 · Кейіпкерің кім және неге осылай?","2 · Қандай prompt жаздың, қандай нұсқаны таңдадың?","3 · Растр мен векторды қатар көрсет, үлкейтіп вектордың артықшылығын түсіндір","4 · Ең қиын жері не болды?"],"notes":"Әр оқушыға 2 минут, 1 сұрақ. 40 минутта 25+ оқушы үлгермейді: қорғауды 2 сабаққа бөліңіз немесе жұптық қорғауға ауыстырыңыз."},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Сын-талқылау ережесі","bullets":["«Маған ұнағаны …» деп бастаймыз","«Мен ұсынар едім …» деп аяқтаймыз","Жұмыс туралы айтамыз, адам туралы емес","Алған кеңестен бір нәрсені өзгертіп көрсетеміз"],"notes":"Сын кеңес ретінде айтылуы керек. Қорғау критерийінің 5 балы — сын бойынша өзгертіп көрсеткені."},{"type":"content","pageType":"slide","templateId":"practice","kind":"practice","title":"Практика: қорғау және портфолио","bullets":["1. Растр мен векторды қатар қойып, жобаңды қорға","2. Бір сыныптасыңа «ұнағаны / ұсынатыным» айт","3. Кеңес бойынша бір өзгеріс енгіз","4. Portfolio файлына «Жоба 1 · Стикерпак» бетін қос: дейін/кейін және 3 сөйлемдік рефлексия (не үйрендім, не қиын болды, нені өзгертер едім)"],"notes":"Портфолио: бір бет = бір жоба, бет атауы = жоба аты."},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Бағалау критерийі","bullets":["Идея және мақсат: 5 — жұмыс кім үшін және не үшін екені айқын, пайдалы · 3 — айтылған, бірақ жалпы · 1 — түсініксіз","Дизайн сапасы: 5 — түс, қаріп, композиция таза, мәтін оқылады · 3 — кей жерлері тартымсыз · 1 — шатасқан","Техника: 5 — қабаттар аталған, құралдар дұрыс қолданылған · 3 — бір бөлігі ретсіз · 1 — көбі ретсіз","Қорғау және кері байланыс: 5 — жұмысын түсіндірді, кеңес бойынша өзгерткенін көрсетті · 3 — түсіндірді, өзгертпеді · 1 — түсіндіре алмады"],"notes":"Әр критерий 0–5 балл, барлығы 20. Үш деңгей — 5, 3, 1; аралық бағаны 4, 2, 0 деп қоюға болады."},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Өзіңді тексер · 1","prompt":"Векторлық стикердің растрдан басты артықшылығы?","options":["Файлы әрқашан үлкен","Қанша үлкейтсе де анық қалады","Түстері көп","Фотоға ұқсас"],"answer":1,"explanation":"Вектор өлшемге тәуелсіз анық қалады.","points":1},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Өзіңді тексер · 2","prompt":"Қайсысы дұрыс сын?","options":["Бұл жаман","Маған ұнағаны — түстер, мен ұсынар едім — контурды тегіс ету","Мен жасар едім жақсырақ","Ештеңе айтпау"],"answer":1,"explanation":"Дұрыс сын нақты және кеңес түрінде айтылады.","points":1},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Өзіңді тексер · 3","prompt":"Портфолио бетіне не қосылады?","options":["Тек сурет","Дейін/кейін және 3 сөйлемдік рефлексия","Тек атау","Достың жұмысы"],"answer":1,"explanation":"Дейін/кейін және рефлексия — портфолио талабы.","points":1}]$sl$::jsonb)
  ) as t(title, position, plan, terms, slides)
  loop
    select cl.lesson_id into v_lesson from public.cf_curr_lessons cl where cl.module_id = v_module and cl.position = v_spec.position limit 1;
    if v_lesson is null then
      insert into public.cf_lessons (school_id, owner_id, title, subject, plan, slides, terms)
      values (v_school, v_owner, v_spec.title, 'Графикалық дизайн', v_spec.plan, v_spec.slides, v_spec.terms) returning id into v_lesson;
    else
      update public.cf_lessons set title = v_spec.title, subject = 'Графикалық дизайн', plan = v_spec.plan, slides = v_spec.slides, terms = v_spec.terms, updated_at = now() where id = v_lesson;
    end if;
    insert into public.cf_curr_lessons (lesson_id, module_id, position) values (v_lesson, v_module, v_spec.position)
    on conflict (lesson_id) do update set module_id = excluded.module_id, position = excluded.position;
    v_lesson := null;
  end loop;
