    ($sl$9.4 Constraints және responsive$sl$, 3, $sl${"summary":"Бір экранды телефонға және компьютерге бейімдеу: Constraints, Fill және екі өлшемді макет.","objectives":["Constraints параметрлерін түсіндіру","Бір экранды екі өлшемге бейімдеу","Бейімделуді Frame өлшемін өзгертіп тексеру"],"grade":9,"duration":"40 минут"}$sl$::jsonb, $sl$[{"term":"Constraints","definition":"Frame өлшемі өзгергенде элементтің қалай қозғалатыны"},{"term":"responsive","definition":"экран өлшеміне бейімделетін дизайн"},{"term":"breakpoint","definition":"макет өзгеретін экран ені"}]$sl$::jsonb, $sl$[{"type":"title","pageType":"slide","templateId":"title","title":"Constraints және responsive","subtitle":"9.4 · Телефон және компьютер"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Бүгін сен үйренесің","bullets":["1 · Constraints параметрлерін түсіндіру","2 · Бір экранды телефонға және компьютерге бейімдеу","3 · Frame өлшемін өзгертіп, бейімделуді тексеру"],"notes":"Жылыту: өз сайтыңыз/қосымшаңыз телефонда да, компьютерде де бірдей көріне ме? Бейімделу — қазіргі дизайнның негізі."},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Constraints","bullets":["Frame өлшемі өзгергенде элемент қалай қозғалады","Көлденең: Left, Right, Left & Right, Center, Scale","Тік: Top, Bottom, Top & Bottom, Center, Scale","Мысал: батырма төменде тұру керек → Bottom"],"notes":"Тексеру әдісі: Frame-дің өлшемін сүйреп өзгертіп, элементтердің мінезін көру."},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Екі өлшем","bullets":["Телефон шамамен 390 px, компьютер шамамен 1440 px ен","Телефонда бір баған, компьютерде бірнеше баған","Негізгі әдіс: Auto layout + Fill container + Constraints"],"code":"Телефон (390)     Компьютер (1440)\n┌────────┐        ┌───────────────────┐\n│ карт.1 │        │ карт.1 │ карт.2 │ карт.3 │\n│ карт.2 │        └───────────────────┘\n│ карт.3 │\n└────────┘","lang":"t