    ($sl$9.6 Жоба: UX-аудит$sl$, 5, $sl${"summary":"Таңдалған қосымшаның 3 негізгі мәселесін скриншотпен дәлелдеу: мәселе, бұзылған ереже, әсер, ұсыныс.","objectives":["Қосымшаны таңдап, мәселелерді табу","Әр мәселені скриншотпен және эвристикамен дәлелдеу","Мәселелерді маңыздылығы бойынша реттеу"],"grade":9,"duration":"40 минут"}$sl$::jsonb, $sl$[{"term":"UX-аудит","definition":"өнімнің ыңғайсыз жерлерін жүйелі іздеу"},{"term":"маңыздылық","definition":"мәселенің қолданушыға қаншалықты зиян екені (1–3)"},{"term":"скриншот","definition":"экранның суреті"}]$sl$::jsonb, $sl$[{"type":"title","pageType":"slide","templateId":"title","title":"Жоба: UX-аудит","subtitle":"9.6 · 3 мәселе, дәлел, ұсыныс"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Бүгін сен үйренесің","bullets":["1 · Қосымшаны таңдап, мәселелерді табу","2 · Әр мәселені скриншотпен және эвристикамен дәлелдеу","3 · Мәселелерді маңыздылығы бойынша реттеу"],"notes":"Жоба 1-дің бірінші жартысы. Қосымшаны таңдау ережесі: оқушы өзі қолданатын, мектеп рұқсат еткен, жеке дерегі скриншотта көрінбейтін қосымша."},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Мәселе карточкасы","bullets":["Экран: қай жерде болды (скриншот)","Мәселе: нақты не қиын","Ереже: қай эвристика бұзылған","Әсер: қолданушыға не болады","Маңыздылық: 1 (шағын), 2 (орта), 3 (маңызды)","Ұсыныс: қалай түзетуге болады"],"notes":"9.1 мысалындағы форматты қайталайды: мәселе — ереже — әсер — шешім."},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Ескерту","bullets":["Скриншотта өзіңнің немесе басқа адамның жеке деректері (аты, нөмір, хат) көрінбесін","Қажет болса, жасыр немесе қиып ал","Мәселені «ұнамайды» деп емес, ереже және әсер арқылы дәлелде"],"notes":"Соңғы пункт аудиттің сапасын анықтайды: «ұнамайды» — пікір, «батырма басылғанын көрсетпейді» — дәлелді мәселе."},{"type":"solution","pageType":"slide","templateId":"worked-example","kind":"exampletask","title":"Бір мәселені дәлелдейміз","sections":[{"h":"Шарты","text":"Мектеп сайтындағы мәзірдегі мәселені карточкаға жаз."},{"h":"Қадамдар","bullets":["Экран: басты бет мәзірінің скриншоты","Мәселе: сабақ кестесін табуға 5 басу керек","Ереже: қарапайымдылық, танып алу","Әсер: оқушылар кестені таппай, сұрайды","Маңыздылық 3 · Ұсыныс: басты бетке «Кесте» батырмасы"]},{"h":"Нәтиже","text":"Скриншоты, эвристикасы, әсері және ұсынысы бар мәселе карточкасы","hide":true}],"notes":"Бұл — үлгі, оқушылар өздерінің қосымшасымен жасайды."},{"type":"content","pageType":"slide","templateId":"practice","kind":"practice","title":"Практика: 3 мәселе","bullets":["1. Қосымшаны таңда және мұғалімге атын айт","2. Figma-да 3 мәселе карточкасын жаса: скриншот, мәселе, ереже, әсер, маңыздылық, ұсыныс","3. Мәселелерді маңыздылығы бойынша реттеп, ең маңыздысын бірінші қой","4. Жеке деректердің көрінбейтінін тексер"],"notes":"Тапсырма Figma-да орындалады. Мұғалімнің белгілеуі: орындалды — 1, орындалмады — 0."},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Бағалау критерийі","bullets":["1 · 3 мәселе скриншотпен көрсетілген","2 · Әр мәселеге эвристика мен әсер жазылған","3 · Маңыздылық берілген, реттелген","4 · Жеке деректер жасырылған","Әр критерий: орындалды — 1, орындалмады — 0. Барлығы 4 ұпай."]},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Өзіңді тексер · 1","prompt":"Мәселені қалай дұрыс дәлелдейміз?","options":["«Маған ұнамайды»","Скриншот, бұзылған ереже және қолданушыға әсері арқылы","Тек түсі туралы","Пікір сұрамай"],"answer":1,"explanation":"Дәлел — скриншот, ереже, әсер.","points":1},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Өзіңді тексер · 2","prompt":"Скриншотқа не болмауы керек?","options":["Батырма","Жеке деректер (аты, нөмір, хат)","Мәзір","Тақырып"],"answer":1,"explanation":"Жеке деректерді жасыру немесе қию керек.","points":1},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Өзіңді тексер · 3","prompt":"Қай мәселе ең маңызды (3)?","options":["Қаріп сәл ұсақ","Төлем жасау батырмасы жұмыс істемейді","Логотип сәл ауытқыған","Түс сәл күңгірт"],"answer":1,"explanation":"Негізгі мақсатқа жетуге бөгет болатын мәселе — ең маңызды.","points":1}]$sl$::jsonb),
