","kind":"check","title":"Өзіңді тексер · 3","prompt":"«Дейін / Кейін» не үшін керек?","options":["Жұмыстың көлемін көрсету","Өзгерістің нәтижесін көрсету","Файл аты үшін","Түстер үшін"],"answer":1,"explanation":"Салыстыру жақсарғанын дәлелдейді.","points":1}]$sl$::jsonb),
    ($sl$9.8 Жобаны қорғау$sl$, 7, $sl${"summary":"«Дейін / кейін» салыстыру, сын-талқылау, портфолио және тоқсандық баға.","objectives":["UX-аудит пен redesign-ды 2 минутта қорғау","Сынды қабылдап, бір өзгеріс енгізу","Жобаны портфолиоға салу"],"grade":9,"duration":"40 минут"}$sl$::jsonb, $sl$[{"term":"critique","definition":"сын-талқылау"},{"term":"портфолио","definition":"жұмыстар жинағы"},{"term":"рефлексия","definition":"өз жұмысың туралы ойлану"}]$sl$::jsonb, $sl$[{"type":"title","pageType":"slide","templateId":"title","title":"Жобаны қорғау","subtitle":"9.8 · UX-аудит және redesign"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Бүгін сен үйренесің","bullets":["1 · Аудит пен redesign-ды 2 минутта қорғау","2 · Сынды қабылдап, бір өзгеріс енгізу","3 · Жобаны портфолиоға салу"],"notes":"Тоқсандық жиынтық баға. Критерийлер 0–5, барлығы 20. 5 баллдық бағаға ауыстыру шкаласын мектептің талабымен бекітіңіз."},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Қорғау құрылымы (2 минут)","bullets":["1 · Қай қосымша және не үшін таңдадың?","2 · 3 мәселе, ең маңыздысын дәлелде (ереже + әсер)","3 · «Дейін / Кейін» экранда көрсет","4 · Қандай шешім қабылдадың және неге?"],"notes":"40 минутқа үлкен сынып сыймайды: қорғауды жұпта немесе 2 сабаққа бөліңіз."},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Сын-талқылау ережесі","bullets":["«Маған ұнағаны …» деп бастаймыз","«Мен ұсынар едім …» деп аяқтаймыз","Жұмыс туралы, адам туралы емес","Бір кеңес бойынша экранды өзгертіп көрсетеміз"],"notes":"Қорғау критерийінің жоғары бағасы — кеңес бойынша өзгерткенін көрсету."},{"type":"content","pageType":"slide","templateId":"practice","kind":"practice","title":"Практика: қорғау және портфолио","bullets":["1. Жобаңды қорға: мәселе, ереже, «Дейін / Кейін»","2. Бір сыныптасыңа «ұнағаны / ұсынатыным» айт","3. Кеңес бойынша бір өзгеріс енгіз","4. Portfolio файлына «Жоба 1 · UX-аудит және redesign» бетін қос: дейін/кейін және 3 сөйлемдік рефлексия"],"notes":"Портфолио: бір бет = бір жоба."},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Бағалау критерийі","bullets":["Идея және мақсат: 5 — жұмыс кім үшін және не үшін екені айқын, пайдалы · 3 — айтылған, бірақ жалпы · 1 — түсініксіз","Дизайн сапасы: 5 — түс, қаріп, композиция таза, мәтін оқылады · 3 — кей жерлері тартымсыз · 1 — шатасқан","Техника: 5 — қабаттар аталған, құралдар дұрыс қолданылған · 3 — бір бөлігі ретсіз · 1 — көбі ретсіз","Қорғау және кері байланыс: 5 — жұмысын түсіндірді, кеңес бойынша өзгерткенін көрсетті · 3 — түсіндірді, өзгертпеді · 1 — түсіндіре алмады"],"notes":"Әр критерий 0–5 балл, барлығы 20. Үш деңгей — 5, 3, 1; аралық бағаны 4, 2, 0 деп қоюға болады."},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Өзіңді тексер · 1","prompt":"Қорғауда ең маңыздысы не?","options":["Тек әдемі көрінісі","Мәселені, ережені, шешімді дәлелдеу","Тез сөйлеу","Көп мәтін"],"answer":1,"explanation":"Дәлелдеу — мәселе, ереже, әсер, шешім.","points":1},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Өзіңді тексер · 2","prompt":"Қай сөйлем дұрыс сын?","options":["Нашар жұмыс","Маған ұнағаны — түзетілген мәзір, мен ұсынар едім — контрастты арттыру","Мен басқаша жасар едім","Ештеңе айтпаймын"],"answer":1,"explanation":"Дұрыс сын нақты және кеңес түрінде.","points":1},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Өзіңді тексер · 3","prompt":"«Дейін / Кейін» портфолиоға не үшін қосылады?","options":["Көлем үшін","Дамуды көрсету үшін","Түс үшін","Жасыру үшін"],"answer":1,"explanation":"Салыстыру өсуді және нәтижені көрсетеді.","points":1}]$sl$::jsonb)
  ) as t(title, position, plan, terms, slides)
  loop
    select cl.lesson_id into v_lesson from public.cf_curr_lessons cl where cl.module_id = v_module and cl.position = v_spec.position limit 1;
    if v_lesson is null then
      insert into public.cf_lessons (school_id, owner_id, title, subject, plan, slides, terms)
      values (v_school, v_owner, v_spec.title, 'Графикалық дизайн', v_spec.plan, v_spec.slides, v_spec.terms) returning id into v_lesson;
    else
      update public.cf_lessons set title = v_spec.title, subject = 'Графикалық дизайн', plan = v_spec.plan, slides = v_spec.slides, terms = v_spec.terms, updated_at = now() where id = v_lesson;
    end if;
    insert into public.cf_curr_lessons (lesson_id, module_id, position) values (v_lesson, v_module, v_spec.position)
    on conflict (lesson_id) do update set module_id = excluded.module_id, position = excluded.position;
    v_lesson := null;
  end loop;
end;
